## Code Example
```javascript
function countPaths(grid, K) {
  const m = grid.length;
  const n = grid[0].length;
  if (grid[0][0] === 1 || grid[m-1][n-1] === 1) return 0;

  const dp = Array.from({ length: m }, () =>
    Array.from({ length: n }, () =>
      Array.from({ length: K + 1 }, () => [0, 0])
    )
  );

  dp[0][0][0][0] = 1; // right
  dp[0][0][0][1] = 1; // down

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) continue;
      for (let t = 0; t <= K; t++) {
        // from left (coming from right)
        if (j > 0) {
          dp[i][j][t][0] += dp[i][j-1][t][0]; // same direction
          if (t > 0) dp[i][j][t][0] += dp[i][j-1][t-1][1]; // turn
        }
        // from top (coming from down)
        if (i > 0) {
          dp[i][j][t][1] += dp[i-1][j][t][1]; // same direction
          if (t > 0) dp[i][j][t][1] += dp[i-1][j][t-1][0]; // turn
        }
      }
    }
  }

  let ans = 0;
  for (let t = 0; t <= K; t++) {
    ans += dp[m-1][n-1][t][0] + dp[m-1][n-1][t][1];
  }
  return ans;
}
```

This runs in O(m × n × K) time and O(m × n × K) space.

## Why This Problem Is Asked
This problem combines prefix DP with an inner backward sweep to compute the optimal segment ending at each position. It tests understanding of state decomposition, reconstruction logic, and handles edge cases like negative values naturally.

## Key Concepts
- DP state: dp[i][t] tracks the optimal value using the first i elements with t segments
- Inner loop: expanding the left boundary computes segment maximum on the fly
- Reconstruction: store predecessor pointers to recover exact subarray boundaries
- Complexity: O(n²k) time, O(nk) space

## Code Example
```javascript
function maxValueSubarrays(A, k) {
    const n = A.length;
    const dp = Array(n + 1).fill(null).map(() => Array(k + 1).fill(-Infinity));
    const prev = Array(n + 1).fill(null).map(() => Array(k + 1).fill(0));
    dp[0][0] = 0;

    for (let i = 1; i <= n; i++) {
        for (let t = 1; t <= k; t++) {
            let curMax = -Infinity;
            for (let l = i; l >= 1; l--) {
                curMax = Math.max(curMax, A[l - 1]);
                const val = (dp[l - 1][t - 1] !== -Infinity ? dp[l - 1][t - 1] + curMax : -Infinity);
                if (val > dp[i][t]) {
                    dp[i][t] = val;
                    prev[i][t] = l;
                }
            }
        }
    }

    const result = [];
    let i = n, t = k;
    while (t > 0 && i > 0) {
        const l = prev[i][t];
        result.unshift([l, i]);
        i = l - 1;
        t--;
    }
    return { value: dp[n][k], boundaries: result };
}
```

## Why This Is Asked
New DP angle focusing on subarray range gain with exact k partitions.

## Key Concepts
- DP partitioning
- Precomputing range max/min
- Reconstruction through pointers
- Time: O(n^2 k); Space: O(nk)

## Code Example
```javascript
function maxGainKSubarrays(A, k){
  const n = A.length;
  const gain = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let l=0;l<n;l++){
    let mn = A[l], mx = A[l];
    for(let r=l;r<n;r++){
      mn = Math.min(mn, A[r]);
      mx = Math.max(mx, A[r]);
      gain[l][r] = mx - mn;
    }
  }
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const take = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  dp[0][0] = 0;
  for(let i=1;i<=n;i++){
    for(let t=0;t<=Math.min(i,k);t++){
      dp[i][t] = dp[i-1][t];
      take[i][t] = take[i-1][t];
      if(t>0){
        for(let l=1;l<=i;l++){
          const val = dp[l-1][t-1] + gain[l-1][i-1];
          if(val>dp[i][t]){ dp[i][t] = val; take[i][t] = l-1; }
        }
      }
    }
  }
  const res = [];
  let i=n, t=k;
  while(t>0){
    const lminus1 = take[i][t];
    const l = lminus1 + 1;
    res.unshift([l, i]);
    i = lminus1; t--;
  }
  return {score: dp[n][k], blocks: res};
}
```

